    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours:
        return out

    for r, c in sixes:
        out[r][c] = 0

    r0 = min(r for r, c in fours)
    r1 = max(r for r, c in fours)
    c0 = min(c for r, c in fours)
    c1 = max(c for r, c in fours)
    bh, bw = r1 - r0 + 1, c1 - c0 + 1

    if bw > bh:  # mirror vertically
        above, below = r0, h - 1 - r1
        if above >= bh and below < bh:
            direction = -1
        elif below >= bh and above < bh:
            direction = 1
        elif above >= bh and below >= bh:
            six_center = sum(r for r, c in sixes) / len(sixes) if sixes else h
            direction = -1 if six_center > (r0 + r1) / 2 else 1
        else:
            direction = 1 if below > above else -1
        for r, c in fours:
            rr = 2 * r0 - 1 - r if direction < 0 else 2 * r1 + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:  # mirror horizontally
        left, right = c0, w - 1 - c1
        if left >= bw and right < bw:
            direction = -1
        elif right >= bw and left < bw:
            direction = 1
        elif left >= bw and right >= bw:
            direction = 1
        else:
            direction = 1 if right > left else -1
        for r, c in fours:
            cc = 2 * c0 - 1 - c if direction < 0 else 2 * c1 + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4

    return out
